import * as T from 'three';
class Particles {
 constructor(scene,count,additive){this.count=count;this.cursor=0;this.items=Array(count);this.position=new Float32Array(count*3);this.color=new Float32Array(count*3);this.size=new Float32Array(count);this.alpha=new Float32Array(count);const geometry=new T.BufferGeometry();for(const [name,data,size] of [['position',this.position,3],['pColor',this.color,3],['pSize',this.size,1],['pAlpha',this.alpha,1]])geometry.setAttribute(name,new T.BufferAttribute(data,size));this.geometry=geometry;const material=new T.ShaderMaterial({transparent:true,depthWrite:false,blending:additive?T.AdditiveBlending:T.NormalBlending,uniforms:{pixelScale:{value:innerHeight/2}},vertexShader:'attribute vec3 pColor;attribute float pSize;attribute float pAlpha;varying vec3 vColor;varying float vAlpha;uniform float pixelScale;void main(){vColor=pColor;vAlpha=pAlpha;vec4 mv=modelViewMatrix*vec4(position,1.0);gl_PointSize=pSize*pixelScale/max(1.0,-mv.z);gl_Position=projectionMatrix*mv;}',fragmentShader:'varying vec3 vColor;varying float vAlpha;void main(){float d=length(gl_PointCoord-0.5)*2.0;if(d>1.0)discard;float a=pow(1.0-d,1.5)*vAlpha;gl_FragColor=vec4(vColor,a);}'});this.mesh=new T.Points(geometry,material);this.mesh.frustumCulled=false;scene.add(this.mesh);}
 emit(position,velocity,life,size,color,kind='spark'){this.items[this.cursor]={position:position.clone(),velocity:velocity.clone(),life,remaining:life,size,color:new T.Color(color),kind};this.cursor=(this.cursor+1)%this.count;}
 update(dt){for(let i=0;i<this.count;i++){const p=this.items[i];if(!p||p.remaining<=0){this.alpha[i]=0;continue;}p.remaining-=dt;p.position.addScaledVector(p.velocity,dt);if(p.kind==='spark')p.velocity.y-=14*dt;else if(p.kind==='smoke')p.velocity.y+=.6*dt;const age=1-p.remaining/p.life;this.position.set(p.position.toArray(),i*3);let c=p.color;if(p.kind==='flame'){c=c.clone().lerp(new T.Color(0xe6330d),age);this.size[i]=p.size*(1-age*.8);}else this.size[i]=p.size*(p.kind==='smoke'?.6+age*3:1);this.color.set(c.toArray(),i*3);this.alpha[i]=Math.max(0,1-age)*(p.kind==='smoke'?.6:1);}
 for(const attribute of Object.values(this.geometry.attributes))attribute.needsUpdate=true;}
 dispose(){this.geometry.dispose();this.mesh.material.dispose();this.mesh.removeFromParent();}
}
export class RaceEffects {
 constructor(scene,car,camera,environment){this.scene=scene;this.car=car;this.camera=camera;this.environment=environment;this.add=new Particles(scene,1800,true);this.smoke=new Particles(scene,500,false);this.markIndex=0;this.markTimer=0;this.shake=0;this.fractions={flame:0,smoke:0,streak:0,weather:0};const b=new T.Box3().setFromObject(car),size=b.getSize(new T.Vector3());this.tail=-size.z/2+.05;this.rearTrack=size.x*.36;this.rearAxle=-size.z/2+size.z*.2;
 const canvas=document.createElement('canvas');canvas.width=32;canvas.height=128;const ctx=canvas.getContext('2d');for(let y=0;y<128;y+=4){ctx.fillStyle=y%8===0?'#0505059e':'#0505057a';ctx.fillRect(4,y,24,4);}ctx.fillStyle='#05050538';ctx.fillRect(0,0,4,128);ctx.fillRect(28,0,4,128);
 this.marks=new T.InstancedMesh(new T.PlaneGeometry(.3,1.8),new T.MeshBasicMaterial({map:new T.CanvasTexture(canvas),transparent:true,depthWrite:false,side:T.DoubleSide}),220);this.marks.renderOrder=5;this.marks.frustumCulled=false;const zero=new T.Matrix4().makeScale(0,0,0);for(let i=0;i<220;i++)this.marks.setMatrixAt(i,zero);scene.add(this.marks);this.tmp=new T.Object3D();
 }
 burst(name,position){const collect=name==='spark',strength=name==='takedown'?1:.55,count=collect?36:32;for(let i=0;i<count;i++){const velocity=new T.Vector3((Math.random()-.5)*14,Math.random()*10,(Math.random()-.5)*14);this.add.emit(position,velocity,collect?.6:.45,collect?.035:.06,collect?0x73f7ff:0xffbf4d,collect?'pickup':'spark');}if(!collect)this.shake=Math.max(this.shake,strength);}
 spawnRate(key,rate,dt,fn){this.fractions[key]+=rate*dt;while(this.fractions[key]>=1){this.fractions[key]--;fn();}}
 update(e,dt){this.car.updateWorldMatrix(true,false);const sliding=e.drifting&&Math.abs(e.steering)>.15&&e.speed>20,local=(x,y,z)=>this.car.localToWorld(new T.Vector3(x,y,z)),direction=(x,y,z)=>new T.Vector3(x,y,z).applyQuaternion(this.car.quaternion);
 this.spawnRate('flame',e.boosting?(e.shockwave?440:280):0,dt,()=>{const p=local(Math.random()<.5?-.45:.45,.42,this.tail);this.add.emit(p,direction((Math.random()-.5)*.5,0,-7-Math.random()*4),.11+Math.random()*.1,e.shockwave?.45:.32,e.shockwave?0xd980ff:0x99e6ff,'flame');});
 this.spawnRate('smoke',sliding?120:e.offRoad&&e.speed>15?60:0,dt,()=>{const p=local((Math.random()<.5?-1:1)*this.rearTrack,.25,this.rearAxle),v=direction((Math.random()-.5)*1.5,.4,-1);this.smoke.emit(p,v,1.2+Math.random()*.8,.4+Math.random()*.6,e.offRoad&&!sliding?0xa88f6b:0xebebeb,'smoke');});
 this.spawnRate('streak',e.boosting?260:e.speed/(e.car.speed+e.upgrade*3)>.92?60:0,dt,()=>{const a=Math.random()*Math.PI*2,r=2.6+Math.random()*2.9;const p=this.camera.localToWorld(new T.Vector3(Math.cos(a)*r,Math.sin(a)*r,-30));const v=new T.Vector3(0,0,70+Math.random()*20).applyQuaternion(this.camera.quaternion);this.add.emit(p,v,.35,.03,0xffffff,'streak');});
 if(sliding&&!e.offRoad){this.markTimer+=dt*e.speed;if(this.markTimer>1.6){this.markTimer=0;for(const side of [-1,1]){const p=local(side*this.rearTrack,0,this.rearAxle);this.tmp.position.set(p.x,.118,p.z);this.tmp.rotation.set(-Math.PI/2,0,-this.car.rotation.y);this.tmp.scale.setScalar(1);this.tmp.updateMatrix();this.marks.setMatrixAt(this.markIndex,this.tmp.matrix);this.markIndex=(this.markIndex+1)%220;}this.marks.instanceMatrix.needsUpdate=true;}}
 for(const signal of e.signals)if(['spark','impact','takedown','land'].includes(signal))this.burst(signal,this.car.position.clone().add(new T.Vector3(0,.7,0)));
 const snow=e.c.setting==='SKI VILLAGE'||e.c.setting==='SUMMIT STATION',rain=e.c.environment===1&&e.c.route!==2;this.spawnRate('weather',snow||rain?70:12,dt,()=>{const p=this.car.position.clone().add(new T.Vector3((Math.random()-.5)*100,rain||snow?20:2,(Math.random()-.5)*100));this.add.emit(p,new T.Vector3(0,rain?-18:snow?-2:.4,0),6,rain?.035:.08,rain?0x8eadd3:0xffebc3,'weather');});
 this.add.update(dt);this.smoke.update(dt);if(this.shake>0){this.shake=Math.max(0,this.shake-dt*2.6);const t=e.elapsed*47,amount=this.shake*this.shake*.28;this.camera.position.x+=Math.sin(t)*amount;this.camera.position.y+=Math.cos(t*1.3)*amount*.7;}
 }
 dispose(){this.add.dispose();this.smoke.dispose();this.marks.geometry.dispose();this.marks.material.dispose();this.marks.removeFromParent();}
}
